import { randomBytes } from "node:crypto";
import {
  chmodSync,
  existsSync,
  mkdirSync,
  readFileSync,
  writeFileSync,
} from "node:fs";
import { dirname } from "node:path";
import { MAIN_PORTS, MAIN_SITE_URL } from "../dev/worktree-env.ts";

export const LOCAL_CONVEX_URL = `http://127.0.0.1:${MAIN_PORTS.convex}`;
export const LOCAL_CONVEX_SITE_URL = `http://127.0.0.1:${MAIN_PORTS.convexSite}`;

export const derivedEnvTemplate = (entries: Record<string, string>): string =>
  [
    "# Generated by bun run setup. Local only; never commit.",
    ...Object.entries(entries).map(([name, value]) => `${name}=${value}`),
    "",
  ].join("\n");

export const webEnvTemplate = (overrides?: {
  convexUrl?: string;
  convexSiteUrl?: string;
  siteUrl?: string;
}): string =>
  derivedEnvTemplate({
    VITE_PUBLIC_CONVEX_URL: overrides?.convexUrl ?? LOCAL_CONVEX_URL,
    VITE_PUBLIC_CONVEX_SITE_URL:
      overrides?.convexSiteUrl ?? LOCAL_CONVEX_SITE_URL,
    VITE_PUBLIC_WORKOS_REDIRECT_URI: new URL(
      "/callback",
      overrides?.siteUrl ?? MAIN_SITE_URL
    ).toString(),
  });

export const extensionEnvTemplate = (values: {
  convexUrl: string;
  convexSiteUrl: string;
}): string =>
  derivedEnvTemplate({
    VITE_PUBLIC_CONVEX_URL: values.convexUrl,
    VITE_PUBLIC_CONVEX_SITE_URL: values.convexSiteUrl,
  });

export const ensureFile = (
  path: string,
  contents: string
): "created" | "exists" => {
  if (existsSync(path)) {
    return "exists";
  }
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, contents, { mode: 0o600 });
  return "created";
};

/**
 * A generated value that points at this machine: a loopback URL, or the
 * emulator port next to WORKOS_API_HOSTNAME=localhost. Setup derives these
 * from the checkout's ports, so it refreshes them when the ports change.
 * Every other value is a person's and is never overwritten.
 */
export const isMachineLocalValue = (key: string, value: string): boolean => {
  if (key === "WORKOS_API_PORT") {
    return /^\d+$/.test(value);
  }
  try {
    const { hostname } = new URL(value);
    return ["localhost", "127.0.0.1", "[::1]"].includes(hostname);
  } catch {
    return false;
  }
};

export interface DerivedEnvOptions {
  remove?: readonly string[];
  /** Old key to new key: the line keeps its value under the new name. */
  rename?: Readonly<Record<string, string>>;
  synced?: readonly string[];
}

/**
 * Create or repair a derived dotenv file. Missing keys are appended, synced
 * keys follow their source, and machine-local values (left by an earlier
 * local stack or other ports) are refreshed; custom values are never
 * overwritten.
 */
export const ensureDerivedEnv = (
  path: string,
  entries: Record<string, string>,
  options: DerivedEnvOptions = {}
): "created" | "exists" | "repaired" => {
  const created = ensureFile(path, derivedEnvTemplate(entries));
  if (created === "created") {
    return "created";
  }
  const lines = readFileSync(path, "utf-8").replace(/\s+$/, "").split("\n");
  const keyOf = (line: string) => line.split("=", 1)[0]?.trim() ?? "";
  const inFile = new Set(lines.filter((line) => line.includes("=")).map(keyOf));
  const present = new Set<string>();
  let changed = false;
  const updated = lines.flatMap((raw) => {
    if (!raw.includes("=") || raw.startsWith("#")) {
      return [raw];
    }
    const value = raw.slice(raw.indexOf("=") + 1).trim();
    let key = keyOf(raw);
    let line = raw;
    const renamed = options.rename?.[key];
    if (renamed) {
      // A file with both keeps the new one; otherwise the old value moves.
      changed = true;
      if (inFile.has(renamed) || present.has(renamed)) {
        return [];
      }
      key = renamed;
      line = `${key}=${value}`;
    }
    if (options.remove?.includes(key)) {
      changed = true;
      return [];
    }
    present.add(key);
    const wanted = entries[key];
    if (
      wanted === undefined ||
      value === wanted ||
      !(options.synced?.includes(key) || isMachineLocalValue(key, value))
    ) {
      return [line];
    }
    changed = true;
    return [`${key}=${wanted}`];
  });
  const missing = Object.keys(entries).filter((key) => !present.has(key));
  if (missing.length === 0 && !changed) {
    return "exists";
  }
  const additions = missing.map((key) => `${key}=${entries[key]}`);
  writeFileSync(path, `${[...updated, ...additions].join("\n")}\n`, "utf-8");
  return "repaired";
};

// The emulator wiring, and the API key: the web app signs in as a WorkOS
// public client, and the SDK would use any key it finds.
const REMOVED_WEB_KEYS = [
  "WORKOS_API_HOSTNAME",
  "WORKOS_API_PORT",
  "WORKOS_API_HTTPS",
  "WORKOS_API_KEY",
] as const;

// The web app's names from before it moved to Vite.
const RENAMED_WEB_KEYS = {
  NEXT_PUBLIC_CONVEX_URL: "VITE_PUBLIC_CONVEX_URL",
  NEXT_PUBLIC_CONVEX_SITE_URL: "VITE_PUBLIC_CONVEX_SITE_URL",
  NEXT_PUBLIC_WORKOS_REDIRECT_URI: "VITE_PUBLIC_WORKOS_REDIRECT_URI",
} as const;

export const ensureWebEnv = (
  path: string,
  values: {
    convexUrl: string;
    convexSiteUrl: string;
    siteUrl: string;
    workos: Partial<Record<"WORKOS_CLIENT_ID", string>>;
  }
): "created" | "exists" | "repaired" => {
  if (existsSync(path)) {
    chmodSync(path, 0o600);
  }
  const result = ensureDerivedEnv(
    path,
    {
      ...values.workos,
      VITE_PUBLIC_CONVEX_URL: values.convexUrl,
      VITE_PUBLIC_CONVEX_SITE_URL: values.convexSiteUrl,
      VITE_PUBLIC_WORKOS_REDIRECT_URI: new URL(
        "/callback",
        values.siteUrl
      ).toString(),
      WORKOS_COOKIE_PASSWORD: randomBytes(32).toString("base64url"),
    },
    {
      synced: Object.keys(values.workos),
      remove: REMOVED_WEB_KEYS,
      rename: RENAMED_WEB_KEYS,
    }
  );
  chmodSync(path, 0o600);
  return result;
};
